1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"sort"
8		"unicode/utf8"
9	)
10	
11	// PlanChange is one record in a lineage adjustment plan: the dataset name and
12	// the complete list of its direct upstreams after the batch is applied.
13	//
14	// A change may name a dataset that does not exist yet (it is registered) or an
15	// existing dataset (its direct upstreams are replaced wholesale). Datasets not
16	// mentioned in the plan keep their current direct upstreams.
17	type PlanChange struct {
18		Name      string   `json:"name"`
19		Upstreams []string `json:"upstreams"`
20	}
21	
22	// Plan is a batch of lineage adjustments read from a JSON file.
23	//
24	// Removals names datasets that must be absent from the final graph. Deleting a
25	// name that does not currently exist is a no-op (it is not reported as an
26	// actual removal), so a successful plan can be applied again with empty change
27	// and impact lists. A name listed in Removals must not also appear in Changes.
28	type Plan struct {
29		Changes  []PlanChange `json:"changes"`
30		Removals []string     `json:"removals"`
31	}
32	
33	// Relation is a directed lineage edge: Upstream -> Downstream, meaning the
34	// downstream dataset derives from the upstream dataset.
35	type Relation struct {
36		Upstream   string `json:"upstream"`
37		Downstream string `json:"downstream"`
38	}
39	
40	// GraphDataset is one dataset record in the on-disk graph JSON.
41	type GraphDataset struct {
42		Name      string   `json:"name"`
43		Upstreams []string `json:"upstreams"`
44	}
45	
46	// GraphFile is the on-disk JSON representation of a lineage graph.
47	type GraphFile struct {
48		Datasets []GraphDataset `json:"datasets"`
49	}
50	
51	// BatchReport is the deterministic report produced by preview and apply.
52	//
53	// All slices are non-nil (empty lists encode as [] in JSON). Datasets and name
54	// lists are sorted by name byte order; relation lists are sorted by upstream
55	// then downstream.
56	type BatchReport struct {
57		FinalGraph          GraphFile  `json:"finalGraph"`
58		NewDatasets         []string   `json:"newDatasets"`
59		ChangedDatasets     []string   `json:"changedDatasets"`
60		RemovedDatasets     []string   `json:"removedDatasets"`
61		AddedRelations      []Relation `json:"addedRelations"`
62		RemovedRelations    []Relation `json:"removedRelations"`
63		AffectedDownstreams []string   `json:"affectedDownstreams"`
64	}
65	
66	// graphAdjacency derives the normalized parent map from the in-memory graph.
67	// It rejects nil lineage nodes, empty names, names that are not valid UTF-8
68	// (dataset names or direct upstream references), and references to upstreams
69	// that are not registered; the name/reference rules are the shared ones from
70	// normalizeDatasets and validateAdjacencyReferences, also used by the file and
71	// snapshot readers. It does not check for cycles; use validateAcyclic for that.
72	func graphAdjacency(graph map[string]*Lineage) (adjacency, error) {
73		if graph == nil {
74			return nil, fmt.Errorf("%w: create the graph map with make before validating", ErrNotInitialized)
75		}
76		// Check encoding before anything that would quote these names or turn them
77		// into JSON: a missing-upstream check must not label an unregistered,
78		// non-UTF-8 upstream as ErrNotFound when the name itself is unusable, and
79		// json.Marshal would silently rewrite an invalid byte into U+FFFD. The
80		// check is read-only and reports the offending raw bytes.
81		if err := validateInMemoryNamesUTF8(graph); err != nil {
82			return nil, err
83		}
84		records := make([]GraphDataset, 0, len(graph))
85		for name, entry := range graph {
86			if entry == nil {
87				return nil, fmt.Errorf("%w: dataset %q points to a nil lineage node", ErrInvalidArgument, name)
88			}
89			if name == "" {
90				return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
91			}
92			records = append(records, GraphDataset{Name: name, Upstreams: entry.Parents})
93		}
94		adj, err := normalizeDatasets(records)
95		if err != nil {
96			return nil, err
97		}
98		if err := validateAdjacencyReferences(adj); err != nil {
99			return nil, err
100		}
101		return adj, nil
102	}
103	
104	// ValidateGraph checks the in-memory graph for structural problems: nil nodes,
105	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
106	// references), missing upstreams, and cycles. It does not mutate the graph.
107	//
108	// A graph that fails validation cannot be used as the basis for a batch: an
109	// adjustment plan must not be allowed to paper over pre-existing corruption.
110	func ValidateGraph(graph map[string]*Lineage) error {
111		adj, err := graphAdjacency(graph)
112		if err != nil {
113			return err
114		}
115		return validateAcyclic(adj)
116	}
117	
118	// validatePlanNamesUTF8 rejects a plan in which any name that takes part in
119	// the adjustment — a change record's name, one of its direct upstream names,
120	// or a removals entry — is not valid UTF-8. It is the in-memory counterpart
121	// of the raw-literal scan the plan reader runs (checkPlanNameEncoding): a
122	// Plan built directly in Go never passed through that reader, so without
123	// this gate PreviewBatch and ApplyBatch could register datasets the graph
124	// exporter must refuse and produce reports whose JSON silently rewrites the
125	// bad bytes to U+FFFD (two distinct corrupted names would then print as one).
126	//
127	// Plan order is checked as given: the name of record i comes before its
128	// upstreams, and removals follow all changes, so the first reported position
129	// is the earliest offending name the caller submitted. The error names the
130	// field ("name", "upstreams", or "removals"), the zero-based record or array
131	// position, and — for an upstream — its zero-based position inside that
132	// record. The offending name is quoted with %q, which renders the original
133	// bytes as \x escapes rather than replacing them with U+FFFD, so "p\xff" and
134	// "p\xfe" stay distinguishable. The plan is only read, never normalized or
135	// mutated. Register keeps accepting raw Go strings; this gate belongs only
136	// to the batch boundary, where an unusable name would enter a graph and a
137	// report that are promised exportable.
138	func validatePlanNamesUTF8(plan Plan) error {
139		for i, change := range plan.Changes {
140			if !utf8.ValidString(change.Name) {
141				return fmt.Errorf("%w: field %q in the change record at index %d of %q contains invalid UTF-8 bytes: %q",
142					ErrInvalidArgument, "name", i, "changes", change.Name)
143			}
144			for j, upstream := range change.Upstreams {
145				if !utf8.ValidString(upstream) {
146					// Report the unusable name itself, never a missing-upstream
147					// error: the encoding defect takes precedence over whether
148					// the referenced dataset exists in the final graph.
149					return fmt.Errorf("%w: field %q at index %d in the change record at index %d of %q contains invalid UTF-8 bytes: %q",
150						ErrInvalidArgument, "upstreams", j, i, "changes", upstream)
151				}
152			}
153		}
154		for i, name := range plan.Removals {
155			if !utf8.ValidString(name) {
156				return fmt.Errorf("%w: field %q at index %d contains invalid UTF-8 bytes: %q",
157					ErrInvalidArgument, "removals", i, name)
158			}
159		}
160		return nil
161	}
162	
163	// computeBatch validates the graph and plan, then computes the final adjacency
164	// and the diff report. It does not mutate graph. The returned adjacency is the
165	// graph as it will be after the batch; callers that want to commit it should
166	// pass it to applyAdjacency.
167	func computeBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, adjacency, error) {
168		if err := ValidateGraph(graph); err != nil {
169			return nil, nil, err
170		}
171		original, err := graphAdjacency(graph)
172		if err != nil {
173			return nil, nil, err
174		}
175	
176		// Check every name the plan carries before anything that would quote it,
177		// hash it, or turn the report into JSON: the file reader already rejects
178		// these at the raw-literal level, but a plan constructed directly through
179		// the Go API bypasses that reader, and without this gate it could register
180		// a dataset whose name cannot be exported — two names differing only in an
181		// invalid byte ("p\xff" vs "p\xfe") would even render identically once the
182		// report is marshaled. This is the in-memory counterpart of
183		// checkPlanNameEncoding; see plan_name_encoding.go.
184		if err := validatePlanNamesUTF8(plan); err != nil {
185			return nil, nil, err
186		}
187	
188		// Validate the plan: empty names and duplicate declarations reject the
189		// whole batch, naming the dataset and the reason.
190		declarations := make(map[string]int, len(plan.Changes))
191		for _, change := range plan.Changes {
192			if change.Name == "" {
193				return nil, nil, fmt.Errorf("%w: plan contains a dataset with an empty name", ErrInvalidArgument)
194			}
195			declarations[change.Name]++
196			if declarations[change.Name] > 1 {
197				return nil, nil, fmt.Errorf("%w: dataset %q is declared %d times in the plan", ErrInvalidArgument, change.Name, declarations[change.Name])
198			}
199		}
200	
201		// Validate removals: empty names, duplicate names, and names also declared
202		// as changes all reject the whole batch with the name and reason.
203		removalDecls := make(map[string]int, len(plan.Removals))
204		for _, name := range plan.Removals {
205			if name == "" {
206				return nil, nil, fmt.Errorf("%w: plan removals contain a dataset with an empty name", ErrInvalidArgument)
207			}
208			removalDecls[name]++
209			if removalDecls[name] > 1 {
210				return nil, nil, fmt.Errorf("%w: dataset %q is listed %d times in removals", ErrInvalidArgument, name, removalDecls[name])
211			}
212			if _, ok := declarations[name]; ok {
213				return nil, nil, fmt.Errorf("%w: dataset %q appears in both changes and removals", ErrInvalidArgument, name)
214			}
215		}
216	
217		// Build the final adjacency: start from the original parents, replace each
218		// planned dataset's parents with its normalized upstreams.
219		final := make(adjacency, len(original)+len(plan.Changes))
220		for name, parents := range original {
221			final[name] = append([]string(nil), parents...)
222		}
223		for name := range removalDecls {
224			delete(final, name)
225		}
226		var newNames []string
227		var changedNames []string
228		for _, change := range plan.Changes {
229			wanted := uniqueSorted(change.Upstreams)
230			old, existed := original[change.Name]
231			switch {
232			case !existed:
233				newNames = append(newNames, change.Name)
234			case !stringSliceEqual(old, wanted):
235				changedNames = append(changedNames, change.Name)
236			}
237			final[change.Name] = wanted
238		}
239		sort.Strings(newNames)
240		sort.Strings(changedNames)
241	
242		// Datasets actually removed: names in removals that existed in the
243		// original graph. Deleting a name that does not exist is a no-op and is
244		// not reported, so a successful plan can be applied again with empty lists.
245		var removedNames []string
246		for name := range removalDecls {
247			if _, existed := original[name]; existed {
248				removedNames = append(removedNames, name)
249			}
250		}
251		sort.Strings(removedNames)
252	
253		// Every upstream must resolve to a dataset that exists in the FINAL graph
254		// (new datasets may reference each other regardless of plan order; a
255		// retained dataset that still references a deleted name is rejected here,
256		// with both the referrer and the referenced name in the error). Iterate
257		// over sorted names so the reported pair is deterministic.
258		names := make([]string, 0, len(final))
259		for name := range final {
260			names = append(names, name)
261		}
262		sort.Strings(names)
263		for _, name := range names {
264			for _, parent := range final[name] {
265				if _, ok := final[parent]; !ok {
266					return nil, nil, fmt.Errorf("%w: dataset %q references upstream %q which does not exist in the final graph", ErrNotFound, name, parent)
267				}
268			}
269		}
270		// The final graph must be acyclic, judged after all replacements.
271		if err := validateAcyclic(final); err != nil {
272			return nil, nil, err
273		}
274	
275		added, removed := diffRelations(original, final)
276		affected := affectedDownstreams(original, final, newNames, changedNames, removedNames)
277	
278		report := &BatchReport{
279			FinalGraph:          GraphFile{Datasets: adjacencyToDatasets(final)},
280			NewDatasets:         newNames,
281			ChangedDatasets:     changedNames,
282			RemovedDatasets:     removedNames,
283			AddedRelations:      added,
284			RemovedRelations:    removed,
285			AffectedDownstreams: affected,
286		}
287		// Guarantee non-nil slices so JSON encodes empty lists as [].
288		if report.NewDatasets == nil {
289			report.NewDatasets = []string{}
290		}
291		if report.ChangedDatasets == nil {
292			report.ChangedDatasets = []string{}
293		}
294		if report.RemovedDatasets == nil {
295			report.RemovedDatasets = []string{}
296		}
297		if report.AddedRelations == nil {
298			report.AddedRelations = []Relation{}
299		}
300		if report.RemovedRelations == nil {
301			report.RemovedRelations = []Relation{}
302		}
303		if report.AffectedDownstreams == nil {
304			report.AffectedDownstreams = []string{}
305		}
306		return report, final, nil
307	}
308	
309	// PreviewBatch validates the graph and plan and returns the report WITHOUT
310	// mutating graph. Preview and apply for the same graph and plan produce
311	// identical reports.
312	//
313	// As well as the structural plan rules (empty names, duplicate declarations,
314	// unresolvable upstreams, cycles), every name the plan carries — a change
315	// record's name, any of its direct upstreams, and every removals entry — must
316	// be valid UTF-8 even when the plan was constructed directly in Go instead of
317	// read by UnmarshalPlan. A name that is not valid UTF-8 rejects the whole
318	// batch with ErrInvalidArgument before any dataset could be registered or any
319	// report produced, so a success report can always be marshaled to JSON and an
320	// applied graph can always be exported. See validatePlanNamesUTF8.
321	func PreviewBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
322		report, _, err := computeBatch(graph, plan)
323		return report, err
324	}
325	
326	// ApplyBatch validates the plan, applies it to graph, and returns the report.
327	// On rejection — including a plan that names a dataset, upstream, or removal
328	// with bytes that are not valid UTF-8 — graph is left completely unchanged.
329	func ApplyBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
330		report, final, err := computeBatch(graph, plan)
331		if err != nil {
332			return nil, err
333		}
334		applyAdjacency(graph, final)
335		return report, nil
336	}
337	
338	// applyAdjacency rewrites the in-memory graph to match the final adjacency:
339	// nodes absent from final are removed, parents are replaced, and children are
340	// rebuilt from the parent edges.
341	func applyAdjacency(graph map[string]*Lineage, final adjacency) {
342		for name := range graph {
343			if _, ok := final[name]; !ok {
344				delete(graph, name)
345			}
346		}
347		for name, parents := range final {
348			entry := graph[name]
349			if entry == nil {
350				entry = &Lineage{}
351				graph[name] = entry
352			}
353			entry.Dataset = name
354			entry.Parents = append([]string(nil), parents...)
355			entry.Children = nil
356		}
357		for name, parents := range final {
358			for _, parent := range parents {
359				graph[parent].Children = append(graph[parent].Children, name)
360			}
361		}
362		for name := range graph {
363			graph[name].Children = uniqueSorted(graph[name].Children)
364		}
365	}
366	
367	// diffRelations returns the directed edges present in final but not original
368	// (added) and present in original but not final (removed). Both lists are
369	// sorted by upstream then downstream.
370	func diffRelations(original, final adjacency) (added, removed []Relation) {
371		origEdges := edgeSet(original)
372		finalEdges := edgeSet(final)
373		for e := range finalEdges {
374			if !origEdges[e] {
375				added = append(added, e)
376			}
377		}
378		for e := range origEdges {
379			if !finalEdges[e] {
380				removed = append(removed, e)
381			}
382		}
383		sortRelations(added)
384		sortRelations(removed)
385		return added, removed
386	}
387	
388	// edgeSet collapses the adjacency into a set of upstream->downstream edges.
389	func edgeSet(adj adjacency) map[Relation]bool {
390		set := make(map[Relation]bool)
391		for downstream, parents := range adj {
392			for _, upstream := range parents {
393				set[Relation{Upstream: upstream, Downstream: downstream}] = true
394			}
395		}
396		return set
397	}
398	
399	// sortRelations sorts by upstream then downstream.
400	func sortRelations(rels []Relation) {
401		sort.Slice(rels, func(i, j int) bool {
402			if rels[i].Upstream != rels[j].Upstream {
403				return rels[i].Upstream < rels[j].Upstream
404			}
405			return rels[i].Downstream < rels[j].Downstream
406		})
407	}
408	
409	// affectedDownstreams computes the impact set: starting from the seed datasets
410	// (new, actually changed, or actually removed), follow downstream (children)
411	// edges in BOTH the original and the final graphs. Datasets that are
412	// themselves seeds are excluded from the output; every other reachable dataset
413	// is included once.
414	//
415	// Walking both graphs matters when relations are deleted: a dataset that was
416	// reachable downstream before the change (and thus loses a lineage path) is
417	// still affected even if the edge is gone in the final graph. Removed datasets
418	// are seeds too, so a downstream that lost its upstream node is counted.
419	func affectedDownstreams(original, final adjacency, newNames, changedNames, removedNames []string) []string {
420		seeds := make(map[string]bool, len(newNames)+len(changedNames)+len(removedNames))
421		for _, name := range newNames {
422			seeds[name] = true
423		}
424		for _, name := range changedNames {
425			seeds[name] = true
426		}
427		for _, name := range removedNames {
428			seeds[name] = true
429		}
430	
431		origChildren := invertAdjacency(original)
432		finalChildren := invertAdjacency(final)
433	
434		seen := make(map[string]bool)
435		queue := make([]string, 0, len(seeds))
436		for seed := range seeds {
437			queue = append(queue, seed)
438		}
439		for len(queue) > 0 {
440			node := queue[0]
441			queue = queue[1:]
442			for _, child := range origChildren[node] {
443				if !seen[child] {
444					seen[child] = true
445					queue = append(queue, child)
446				}
447			}
448			for _, child := range finalChildren[node] {
449				if !seen[child] {
450					seen[child] = true
451					queue = append(queue, child)
452				}
453			}
454		}
455	
456		out := make([]string, 0, len(seen))
457		for name := range seen {
458			if !seeds[name] {
459				out = append(out, name)
460			}
461		}
462		sort.Strings(out)
463		return out
464	}
465	
466	// invertAdjacency maps each dataset to the datasets that depend on it (its
467	// children), with each child list sorted by name.
468	func invertAdjacency(adj adjacency) map[string][]string {
469		children := make(map[string][]string, len(adj))
470		for name, parents := range adj {
471			for _, parent := range parents {
472				children[parent] = append(children[parent], name)
473			}
474		}
475		for name := range children {
476			sort.Strings(children[name])
477		}
478		return children
479	}
480	
481	// adjacencyToDatasets renders the final adjacency as sorted, JSON-ready
482	// records with non-nil upstream lists.
483	func adjacencyToDatasets(adj adjacency) []GraphDataset {
484		names := make([]string, 0, len(adj))
485		for name := range adj {
486			names = append(names, name)
487		}
488		sort.Strings(names)
489		ds := make([]GraphDataset, 0, len(names))
490		for _, name := range names {
491			parents := adj[name]
492			if parents == nil {
493				parents = []string{}
494			}
495			ds = append(ds, GraphDataset{Name: name, Upstreams: parents})
496		}
497		return ds
498	}
499	
500	// stringSliceEqual reports whether a and b contain the same strings in the
501	// same order. Both are expected to be sorted and duplicate-free.
502	func stringSliceEqual(a, b []string) bool {
503		if len(a) != len(b) {
504			return false
505		}
506		for i := range a {
507			if a[i] != b[i] {
508				return false
509			}
510		}
511		return true
512	}
513	
514	// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
515	// The graph must satisfy every structure rule a reader enforces; nil nodes,
516	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
517	// references), missing upstreams, and dependency cycles (including a dataset
518	// that lists itself) reject the export with no bytes returned, so a successful
519	// result can always be read back with UnmarshalGraphFile. The check is
520	// read-only: the in-memory graph is never modified.
521	func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
522		adj, err := graphAdjacency(graph)
523		if err != nil {
524			return nil, err
525		}
526		if err := validateAcyclic(adj); err != nil {
527			return nil, err
528		}
529		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
530		return json.MarshalIndent(gf, "", "  ")
531	}
532	
533	// UnmarshalGraphFile parses the on-disk graph JSON and rebuilds the in-memory
534	// graph (parents and derived children). The graph is checked with the same
535	// structural rules a snapshot enforces (empty names, duplicate datasets,
536	// missing upstreams, and cycles); a structurally invalid graph is rejected so
537	// it cannot be used as the basis for a batch. As in a snapshot, a known field
538	// declared twice within the same object — datasets in the graph object, name
539	// or upstreams in a dataset record — is ambiguous and rejects the whole file,
540	// even when the duplicates carry identical values.
541	func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
542		if err := checkGraphFileDuplicateFields(data); err != nil {
543			return nil, err
544		}
545		// Every name the graph carries must survive decoding exactly as written:
546		// a raw literal with invalid UTF-8 bytes or an unpaired surrogate escape
547		// would be silently rewritten to U+FFFD by json.Unmarshal, and a corrupted
548		// upstream could then resolve to a genuinely different dataset (an edge
549		// written as "源" plus a lone \uD800 would point at the real dataset
550		// "源�"). See graph_name_encoding.go.
551		if err := checkGraphNameEncoding(data); err != nil {
552			return nil, err
553		}
554		var gf GraphFile
555		if err := json.Unmarshal(data, &gf); err != nil {
556			return nil, fmt.Errorf("invalid graph JSON: %w", err)
557		}
558		adj, err := validateGraphStructureFromFile(gf.Datasets)
559		if err != nil {
560			return nil, err
561		}
562		// Rebuild children from the parent edges so the in-memory graph is
563		// consistent regardless of how the file was produced.
564		return lineageFromAdjacency(adj), nil
565	}
566	
567	// UnmarshalPlan parses the plan JSON. The plan structure (empty names,
568	// duplicate declarations) is validated later by computeBatch so that preview
569	// and apply share identical rejection behavior.
570	//
571	// A known field declared twice within the same object — changes or removals
572	// at the top level, name or upstreams inside one change record — is
573	// ambiguous: the reader would silently keep only the last declaration and
574	// drop the earlier adjustment. The whole plan is refused instead, even when
575	// the duplicates carry identical values, one is null, or the surviving value
576	// is a legal empty list. Field names are recognized the same way the decoder
577	// resolves them (after JSON unescaping, with Unicode case folding), so a
578	// second declaration spelled "Changes" or "changes" still collides;
579	// dataset names themselves stay case-sensitive. Unknown fields keep their
580	// ignore-everything behavior and may repeat freely.
581	//
582	// Every name that takes part in the adjustment — each change record's name,
583	// every upstreams entry, and every removals entry — must also survive
584	// decoding exactly as written: a raw string literal carrying bytes that are
585	// not valid UTF-8, or a \u escape forming an unpaired surrogate, would be
586	// silently rewritten to U+FFFD by the decoder, and the corrupted name could
587	// then collide with a genuinely different dataset (a removals entry meant
588	// for no one could delete the dataset really named "�"). The whole plan is
589	// refused instead, naming the field and the zero-based record or array
590	// position, even when the corrupted name would only have matched a dataset
591	// that does not exist. A genuine "�", correctly paired surrogate escapes,
592	// and names that merely look like escapes (a backslash before an ordinary
593	// letter) stay legal; unknown fields and their nested strings are not
594	// checked. See plan_name_encoding.go.
595	func UnmarshalPlan(data []byte) (Plan, error) {
596		var p Plan
597		if err := checkPlanDuplicateFields(data); err != nil {
598			return p, err
599		}
600		if err := json.Unmarshal(data, &p); err != nil {
601			return p, fmt.Errorf("invalid plan JSON: %w", err)
602		}
603		if err := checkPlanNameEncoding(data); err != nil {
604			return Plan{}, err
605		}
606		return p, nil
607	}
608	
609	// checkGraphFileDuplicateFields applies the shared repeated-known-field rule
610	// (see duplicate_fields.go) to a standalone graph file, supplying the graph
611	// file's own location: datasets may be declared only once in the top-level
612	// graph object, and name and upstreams only once in each dataset record. The
613	// scan is the same checkGraphObject ParseSnapshot runs on the embedded graph,
614	// so preview, apply, and snapshot can never disagree about a graph that
615	// repeats a known field.
616	func checkGraphFileDuplicateFields(data []byte) error {
617		return runFieldScan(data, func(dec *json.Decoder) error {
618			return checkGraphObject(dec, "at the top level of the graph")
619		})
620	}
621	
622	// checkPlanDuplicateFields applies the shared repeated-known-field rule (see
623	// duplicate_fields.go) to a plan, supplying the plan's own field scope and
624	// locations: changes or removals at the top level, and name or upstreams
625	// inside each change record. A change record carries the same fields as a
626	// dataset record, so both use the shared datasetRecordFields scope and a plan
627	// can never be judged differently from the other documents about what counts
628	// as a repeated field.
629	func checkPlanDuplicateFields(data []byte) error {
630		return runFieldScan(data, func(dec *json.Decoder) error {
631			return checkObjectFields(dec, "at the top level of the plan", []knownField{
632				{name: "changes", nested: func(dec *json.Decoder) error {
633					return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
634						return checkObjectFields(dec, fmt.Sprintf("in the change record at index %d of \"changes\"", index), datasetRecordFields)
635					})
636				}},
637				{name: "removals"},
638			})
639		})
640	}
