1	package chainledger
2	
3	import (
4		"encoding/json"
5		"errors"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	// buildGraph constructs a graph from name -> parents pairs, asserting success.
12	func buildGraph(t *testing.T, pairs ...struct {
13		name    string
14		parents []string
15	}) map[string]*Lineage {
16		t.Helper()
17		graph := map[string]*Lineage{}
18		for _, p := range pairs {
19			if err := Register(graph, Dataset{Name: p.name}, p.parents); err != nil {
20				t.Fatalf("buildGraph: Register(%q, %v) unexpected error: %v", p.name, p.parents, err)
21			}
22		}
23		return graph
24	}
25	
26	// P is a shorthand for building name/parents pairs in test tables.
27	func P(name string, parents ...string) struct {
28		name    string
29		parents []string
30	} {
31		return struct {
32			name    string
33			parents []string
34		}{name, parents}
35	}
36	
37	func planOf(changes ...PlanChange) Plan {
38		return Plan{Changes: changes}
39	}
40	
41	func change(name string, upstreams ...string) PlanChange {
42		return PlanChange{Name: name, Upstreams: upstreams}
43	}
44	
45	// TestBatchMutualSwapSucceeds is the headline scenario: originally B depends
46	// on A. Submitting "A depends on B, B becomes root" must succeed because the
47	// legality is judged on the graph AFTER all replacements.
48	func TestBatchMutualSwapSucceeds(t *testing.T) {
49		graph := buildGraph(t, P("A"), P("B", "A"))
50		plan := planOf(change("A", "B"), change("B"))
51	
52		report, err := PreviewBatch(graph, plan)
53		if err != nil {
54			t.Fatalf("PreviewBatch unexpected error: %v", err)
55		}
56		if got := graph["A"].Parents; len(got) != 0 {
57			t.Fatalf("preview mutated graph: A.Parents = %v", got)
58		}
59	
60		wantChanged := []string{"A", "B"}
61		if !reflect.DeepEqual(report.ChangedDatasets, wantChanged) {
62			t.Errorf("ChangedDatasets = %v, want %v", report.ChangedDatasets, wantChanged)
63		}
64		if len(report.NewDatasets) != 0 {
65			t.Errorf("NewDatasets = %v, want empty", report.NewDatasets)
66		}
67		wantAdded := []Relation{{Upstream: "B", Downstream: "A"}}
68		wantRemoved := []Relation{{Upstream: "A", Downstream: "B"}}
69		if !reflect.DeepEqual(report.AddedRelations, wantAdded) {
70			t.Errorf("AddedRelations = %v, want %v", report.AddedRelations, wantAdded)
71		}
72		if !reflect.DeepEqual(report.RemovedRelations, wantRemoved) {
73			t.Errorf("RemovedRelations = %v, want %v", report.RemovedRelations, wantRemoved)
74		}
75		// No downstream is affected: the swap only repoints A and B, and neither
76		// has other dependents.
77		if len(report.AffectedDownstreams) != 0 {
78			t.Errorf("AffectedDownstreams = %v, want empty", report.AffectedDownstreams)
79		}
80	
81		// Apply and verify the final shape: A depends on B, B is a root.
82		applied, err := ApplyBatch(graph, plan)
83		if err != nil {
84			t.Fatalf("ApplyBatch unexpected error: %v", err)
85		}
86		if !reflect.DeepEqual(applied, report) {
87			t.Errorf("apply report differs from preview:\n apply=%#v\n preview=%#v", applied, report)
88		}
89		if got := graph["A"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
90			t.Errorf("A.Parents = %v, want [B]", got)
91		}
92		if got := graph["B"].Parents; len(got) != 0 {
93			t.Errorf("B.Parents = %v, want empty (root)", got)
94		}
95		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"A"}) {
96			t.Errorf("B.Children = %v, want [A]", got)
97		}
98		if got := graph["A"].Children; len(got) != 0 {
99			t.Errorf("A.Children = %v, want empty", got)
100		}
101		if roots := Roots(graph); !reflect.DeepEqual(roots, []string{"B"}) {
102			t.Errorf("Roots = %v, want [B]", roots)
103		}
104	}
105	
106	// TestBatchRejectsCyclesAfterReplacement verifies that a final graph with a
107	// self-dependency or an indirect cycle is rejected, and that the rejection
108	// names the datasets involved.
109	func TestBatchRejectsCyclesAfterReplacement(t *testing.T) {
110		t.Run("self dependency", func(t *testing.T) {
111			graph := buildGraph(t, P("A"))
112			plan := planOf(change("A", "A"))
113			_, err := PreviewBatch(graph, plan)
114			if !errors.Is(err, ErrCycle) {
115				t.Fatalf("err = %v, want ErrCycle", err)
116			}
117			if !strings.Contains(err.Error(), "A") {
118				t.Errorf("error %q does not name dataset A", err)
119			}
120		})
121	
122		t.Run("indirect cycle through swap", func(t *testing.T) {
123			// A<-B. Plan: A depends on B, B depends on A. Final: A<->B, a cycle.
124			graph := buildGraph(t, P("A"), P("B", "A"))
125			plan := planOf(change("A", "B"), change("B", "A"))
126			_, err := PreviewBatch(graph, plan)
127			if !errors.Is(err, ErrCycle) {
128				t.Fatalf("err = %v, want ErrCycle", err)
129			}
130			for _, name := range []string{"A", "B"} {
131				if !strings.Contains(err.Error(), name) {
132					t.Errorf("error %q does not name dataset %s", err, name)
133				}
134			}
135		})
136	
137		t.Run("new dataset forming a cycle", func(t *testing.T) {
138			graph := buildGraph(t, P("A"))
139			plan := planOf(change("A", "B"), change("B", "A"))
140			_, err := PreviewBatch(graph, plan)
141			if !errors.Is(err, ErrCycle) {
142				t.Fatalf("err = %v, want ErrCycle", err)
143			}
144		})
145	
146		t.Run("rejection leaves graph unchanged", func(t *testing.T) {
147			graph := buildGraph(t, P("A"), P("B", "A"))
148			snapshot := dump(graph)
149			plan := planOf(change("A", "B"), change("B", "A"))
150			if _, err := ApplyBatch(graph, plan); !errors.Is(err, ErrCycle) {
151				t.Fatalf("err = %v, want ErrCycle", err)
152			}
153			if got := dump(graph); got != snapshot {
154				t.Fatalf("ApplyBatch mutated graph on rejection:\n got %s\nwant %s", got, snapshot)
155			}
156		})
157	}
158	
159	// TestBatchNewDatasetsReferenceEachOther verifies that a batch can register
160	// new datasets that depend on each other, regardless of plan order.
161	func TestBatchNewDatasetsReferenceEachOther(t *testing.T) {
162		graph := buildGraph(t, P("A"), P("B", "A"))
163		// Plan is deliberately shuffled: E appears before D, D before C.
164		plan := planOf(change("E", "D"), change("D", "C"), change("C"))
165		report, err := PreviewBatch(graph, plan)
166		if err != nil {
167			t.Fatalf("PreviewBatch unexpected error: %v", err)
168		}
169		wantNew := []string{"C", "D", "E"}
170		if !reflect.DeepEqual(report.NewDatasets, wantNew) {
171			t.Errorf("NewDatasets = %v, want %v", report.NewDatasets, wantNew)
172		}
173		if len(report.ChangedDatasets) != 0 {
174			t.Errorf("ChangedDatasets = %v, want empty", report.ChangedDatasets)
175		}
176		wantAdded := []Relation{
177			{Upstream: "C", Downstream: "D"},
178			{Upstream: "D", Downstream: "E"},
179		}
180		if !reflect.DeepEqual(report.AddedRelations, wantAdded) {
181			t.Errorf("AddedRelations = %v, want %v", report.AddedRelations, wantAdded)
182		}
183		// No downstream of A or B is affected; the new chain is independent.
184		if len(report.AffectedDownstreams) != 0 {
185			t.Errorf("AffectedDownstreams = %v, want empty", report.AffectedDownstreams)
186		}
187	
188		if _, err := ApplyBatch(graph, plan); err != nil {
189			t.Fatalf("ApplyBatch unexpected error: %v", err)
190		}
191		if got := graph["D"].Parents; !reflect.DeepEqual(got, []string{"C"}) {
192			t.Errorf("D.Parents = %v, want [C]", got)
193		}
194		if got := graph["E"].Parents; !reflect.DeepEqual(got, []string{"D"}) {
195			t.Errorf("E.Parents = %v, want [D]", got)
196		}
197		if roots := Roots(graph); !reflect.DeepEqual(roots, []string{"A", "C"}) {
198			t.Errorf("Roots = %v, want [A C]", roots)
199		}
200	}
