392	// TestBatchAffectedDownstreams verifies the impact computation: it starts from
393	// new or changed datasets, follows downstream edges in BOTH the original and
394	// the final graphs, excludes seeds, and dedupes.
395	func TestBatchAffectedDownstreams(t *testing.T) {
396		t.Run("downstream of changed dataset", func(t *testing.T) {
397			// A<-B<-C. B's upstreams change to D (new). C is downstream of B and
398			// is affected. D is new (a seed).
399			graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
400			plan := planOf(change("D"), change("B", "D"))
401			report, err := PreviewBatch(graph, plan)
402			if err != nil {
403				t.Fatalf("PreviewBatch unexpected error: %v", err)
404			}
405			wantAffected := []string{"C"}
406			if !reflect.DeepEqual(report.AffectedDownstreams, wantAffected) {
407				t.Errorf("AffectedDownstreams = %v, want %v", report.AffectedDownstreams, wantAffected)
408			}
409		})
410	
411		t.Run("deleted edge still counts from original graph", func(t *testing.T) {
412			// A<-B<-C. B becomes a root (edge A-B removed). C is still downstream
413			// of B in the final graph, but the impact also follows the original
414			// graph: B's children in the original include C. Either way C is
415			// affected. The key case is when a removed edge hides a dependent in
416			// the final graph.
417			//
418			// A<-B, A<-C (B and C both depend on A). Plan: B becomes root. In the
419			// final graph B has no children, but in the original graph B's children
420			// are empty too. The real test: a dataset that was downstream of B in
421			// the original graph only.
422			//
423			// Construct: A<-B<-C, and C also depends on A. Plan: B becomes root.
424			// Final: B root, C depends on A. C is downstream of B in the original
425			// graph (B->C) but not in the final graph. C must still be affected
426			// because the impact follows the original graph too.
427			graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B", "A"))
428			plan := planOf(change("B"))
429			report, err := PreviewBatch(graph, plan)
430			if err != nil {
431				t.Fatalf("PreviewBatch unexpected error: %v", err)
432			}
433			wantAffected := []string{"C"}
434			if !reflect.DeepEqual(report.AffectedDownstreams, wantAffected) {
435				t.Errorf("AffectedDownstreams = %v, want %v (original-graph dependent must still count)", report.AffectedDownstreams, wantAffected)
436			}
437		})
438	
439		t.Run("seeds excluded and paths deduped", func(t *testing.T) {
440			// A<-B<-C and A<-C. B changes to root. C is downstream of B (original)
441			// and downstream of A (unchanged). C is affected once, not twice.
442			graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B", "A"))
443			plan := planOf(change("B"))
444			report, err := PreviewBatch(graph, plan)
445			if err != nil {
446				t.Fatalf("PreviewBatch unexpected error: %v", err)
447			}
448			count := 0
449			for _, name := range report.AffectedDownstreams {
450				if name == "C" {
451					count++
452				}
453			}
454			if count != 1 {
455				t.Errorf("C counted %d times in AffectedDownstreams %v, want once", count, report.AffectedDownstreams)
456			}
457			// B is a seed (changed) and must not appear in affected.
458			for _, name := range report.AffectedDownstreams {
459				if name == "B" {
460					t.Errorf("seed B appears in AffectedDownstreams %v, must be excluded", report.AffectedDownstreams)
461				}
462			}
463		})
464	
465		t.Run("new dataset with downstream", func(t *testing.T) {
466			// A is new. B (existing) now depends on A, so B is a changed seed. C
467			// depends on B and is unchanged, so C is affected (reachable from the
468			// new dataset A via B in the final graph).
469			graph := buildGraph(t, P("B"), P("C", "B"))
470			plan := planOf(change("A"), change("B", "A"))
471			report, err := PreviewBatch(graph, plan)
472			if err != nil {
473				t.Fatalf("PreviewBatch unexpected error: %v", err)
474			}
475			wantAffected := []string{"C"}
476			if !reflect.DeepEqual(report.AffectedDownstreams, wantAffected) {
477				t.Errorf("AffectedDownstreams = %v, want %v", report.AffectedDownstreams, wantAffected)
478			}
479		})
480	}
