1	// Package chainledger graph structure rules shared by every graph reader.
2	//
3	// Both on-disk graph files (UnmarshalGraphFile) and the graph embedded in a
4	// snapshot (ParseSnapshot) describe the same thing: a set of dataset names and
5	// each dataset's direct upstreams. The rules below are the single authority for
6	// turning that description into the validated, normalized adjacency both
7	// readers build on, so the two file formats can never disagree about whether
8	// one graph is legal or about which lineage relations it expresses:
9	//
10	//   - an empty dataset name is rejected;
11	//   - a dataset declared more than once is rejected;
12	//   - an upstream that is not itself a declared dataset is rejected, with the
13	//     referrer and the referenced name both in the error;
14	//   - a direct self-dependency or any indirect dependency cycle is rejected,
15	//     with the datasets on the cycle named;
16	//   - names are case-sensitive and surrounding whitespace is kept verbatim;
17	//   - every name's RAW string literal must decode faithfully: bytes that are
18	//     not valid UTF-8, or a \u escape forming an unpaired surrogate (a lone
19	//     high or low surrogate, or a low surrogate before its high surrogate),
20	//     reject the whole document — the decoder's U+FFFD rewrite is never kept
21	//     and the offending node or edge is never skipped, even when the rewrite
22	//     would collide with a real dataset or match the snapshot's declared
23	//     content identifier; that raw scan is shared by both graph readers and
24	//     lives in graph_name_encoding.go;
25	//   - record order and upstream order are irrelevant, duplicate upstreams count
26	//     as one relationship, and an empty upstream list marks a root, so an
27	//     empty graph stays legal;
28	//   - a known field declared twice within the same object (datasets in the
29	//     graph object, name or upstreams in a dataset record) is rejected,
30	//     however the two declarations are spelled; that JSON-level scan is
31	//     shared by every document reader and lives in duplicate_fields.go.
32	//
33	// The snapshot-only envelope rules (required fields, format version, content
34	// identifier, and duplicates of the snapshot's own fields) live in
35	// snapshot.go; this file is only the common graph structure.
36	package chainledger
37	
38	import (
39		"fmt"
40		"sort"
41		"strings"
42		"unicode/utf8"
43	)
44	
45	// adjacency maps a dataset name to its sorted, duplicate-free parent names.
46	type adjacency map[string][]string
47	
48	// validateInMemoryNamesUTF8 rejects an in-memory graph whose dataset name or
49	// direct upstream reference is not valid UTF-8.
50	//
51	// Such names cannot exist in a file read by the JSON readers (json.Unmarshal
52	// replaces invalid bytes with U+FFFD), but they can exist in a graph built
53	// through Register or by hand. They must never reach an exporter: encoding/json
54	// would silently replace every invalid byte with U+FFFD, so two different
55	// names ("p\xff" and "p\xfe") could serialize identically and a re-read graph
56	// would no longer be a faithful copy. The whole graph is rejected instead.
57	//
58	// Nodes are visited in name byte order and each node's parents in their stored
59	// order, so the first reported name is stable regardless of map iteration.
60	// The offending name is quoted with %q, which keeps the raw bytes readable
61	// ("p\xff" differs from "p\xfe", and a genuinely valid "p�" is shown as
62	// the replacement character itself). The graph is only read, never modified.
63	// Nil lineage nodes are skipped here; the caller rejects those separately.
64	func validateInMemoryNamesUTF8(graph map[string]*Lineage) error {
65		names := make([]string, 0, len(graph))
66		for name := range graph {
67			names = append(names, name)
68		}
69		sort.Strings(names)
70		for _, name := range names {
71			if !utf8.ValidString(name) {
72				return fmt.Errorf("%w: dataset name %q is not valid UTF-8, so the graph cannot be exported faithfully", ErrInvalidArgument, name)
73			}
74			entry := graph[name]
75			if entry == nil {
76				continue
77			}
78			for _, parent := range entry.Parents {
79				if !utf8.ValidString(parent) {
80					return fmt.Errorf("%w: dataset %q references upstream %q whose name is not valid UTF-8", ErrInvalidArgument, name, parent)
81				}
82			}
83		}
84		return nil
85	}
86	
87	// normalizeDatasets builds the normalized parent adjacency from parsed dataset
88	// records. It rejects empty dataset names and datasets declared more than
89	// once; every surviving upstream list is sorted and deduplicated. It does not
90	// check that upstreams resolve to a declared dataset; use
91	// validateAdjacencyReferences for that.
92	func normalizeDatasets(datasets []GraphDataset) (adjacency, error) {
93		adj := make(adjacency, len(datasets))
94		for _, ds := range datasets {
95			if ds.Name == "" {
96				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
97			}
98			if _, exists := adj[ds.Name]; exists {
99				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
100			}
101			adj[ds.Name] = uniqueSorted(ds.Upstreams)
102		}
103		return adj, nil
104	}
105	
106	// validateAdjacencyReferences rejects an edge whose upstream is not a declared
107	// dataset. Referrers are visited in sorted order with their parents sorted, so
108	// the first reported (referrer, upstream) pair is stable regardless of map
109	// iteration or record order.
110	func validateAdjacencyReferences(adj adjacency) error {
111		names := make([]string, 0, len(adj))
112		for name := range adj {
113			names = append(names, name)
114		}
115		sort.Strings(names)
116		for _, name := range names {
117			for _, parent := range adj[name] {
118				if _, ok := adj[parent]; !ok {
119					return fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
120				}
121			}
122		}
123		return nil
124	}
125	
126	// validateGraphStructureFromFile runs every graph-structure rule shared by the
127	// file readers: it normalizes the records, rejects empty names, duplicate
128	// datasets, and unregistered upstreams, then rejects cycles. The returned
129	// adjacency is the canonical form of the graph's semantics.
130	func validateGraphStructureFromFile(datasets []GraphDataset) (adjacency, error) {
131		adj, err := normalizeDatasets(datasets)
132		if err != nil {
133			return nil, err
134		}
135		if err := validateAdjacencyReferences(adj); err != nil {
136			return nil, err
137		}
138		if err := validateAcyclic(adj); err != nil {
139			return nil, err
140		}
141		return adj, nil
142	}
143	
144	// validateAcyclic reports an error if the parent adjacency contains a cycle
145	// (including a dataset that depends on itself). The error message names the
146	// datasets involved.
147	func validateAcyclic(adj adjacency) error {
148		const (
149			white = 0
150			gray  = 1
151			black = 2
152		)
153		color := make(map[string]int, len(adj))
154		var stack []string
155	
156		var dfs func(node string) error
157		dfs = func(node string) error {
158			color[node] = gray
159			stack = append(stack, node)
160			for _, parent := range adj[node] {
161				switch color[parent] {
162				case gray:
163					// parent is an ancestor of node in the current DFS path, so
164					// following parent edges from parent leads back to parent.
165					idx := 0
166					for stack[idx] != parent {
167						idx++
168					}
169					cycle := make([]string, 0, len(stack)-idx+1)
170					cycle = append(cycle, stack[idx:]...)
171					cycle = append(cycle, parent)
172					return fmt.Errorf("%w: dependency cycle %s", ErrCycle, strings.Join(cycle, " -> "))
173				case white:
174					if err := dfs(parent); err != nil {
175						return err
176					}
177				}
178			}
179			color[node] = black
180			stack = stack[:len(stack)-1]
181			return nil
182		}
183	
184		// Iterate over a sorted snapshot so the first reported cycle is stable
185		// across runs regardless of map iteration order.
186		names := make([]string, 0, len(adj))
187		for name := range adj {
188			names = append(names, name)
189		}
190		sort.Strings(names)
191		for _, name := range names {
192			if color[name] == white {
193				if err := dfs(name); err != nil {
194					return err
195				}
196			}
197		}
198		return nil
199	}
200	
201	// lineageFromAdjacency rebuilds the in-memory graph from validated, normalized
202	// parent adjacency: children are derived from the parent edges, so every
203	// parent/child pair corresponds and both lists stay sorted and duplicate-free.
204	// The result is independent of the caller's record slices.
205	func lineageFromAdjacency(adj adjacency) map[string]*Lineage {
206		graph := make(map[string]*Lineage, len(adj))
207		for name, parents := range adj {
208			graph[name] = &Lineage{
209				Dataset: name,
210				Parents: append([]string(nil), parents...),
211			}
212		}
213		for name, parents := range adj {
214			for _, parent := range parents {
215				graph[parent].Children = append(graph[parent].Children, name)
216			}
217		}
218		for name := range graph {
219			graph[name].Children = uniqueSorted(graph[name].Children)
220		}
221		return graph
222	}
